// Parse Google Sheet rows and find today's schedule.
// Map agent names to agent_ids.

const NAME_TO_ID = {
  'Lupita': 'agent_lupita',
  'Paty':   'agent_paty',
  'Yol':    'agent_yol',
  'Gina':   'agent_gina',
  'Carol':  'agent_carol',
  'Moni':   'agent_moni'
};

// Get today's date in CDMX timezone
const now = new Date();
const cdmx = new Date(now.toLocaleString('en-US', { timeZone: 'America/Mexico_City' }));
const todayStr = cdmx.getFullYear() + '-' +
  String(cdmx.getMonth() + 1).padStart(2, '0') + '-' +
  String(cdmx.getDate()).padStart(2, '0');

const rows = $input.all().map(i => i.json);
const scheduleEntries = [];

for (const row of rows) {
  // Try to parse the date from the 'Fecha' column
  let fecha = row['Fecha'] || row['fecha'] || '';
  if (!fecha) continue;

  // Normalize date format
  fecha = String(fecha).trim();
  let rowDate = '';

  // Try YYYY-MM-DD
  if (/^\d{4}-\d{2}-\d{2}$/.test(fecha)) {
    rowDate = fecha;
  }
  // Try DD/MM/YYYY
  else if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(fecha)) {
    const [d, m, y] = fecha.split('/');
    rowDate = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
  }
  // Try MM/DD/YYYY (US format)
  else if (/^\d{1,2}\/\d{1,2}\/\d{4}$/.test(fecha)) {
    const [m, d, y] = fecha.split('/');
    rowDate = `${y}-${m.padStart(2, '0')}-${d.padStart(2, '0')}`;
  }
  // Try Google Sheets serial number
  else if (/^\d{5}$/.test(fecha)) {
    const epoch = new Date(1899, 11, 30);
    epoch.setDate(epoch.getDate() + parseInt(fecha));
    rowDate = epoch.toISOString().split('T')[0];
  }

  if (rowDate !== todayStr) continue;

  // Extract agents for each shift
  const morning1 = row['Manana 1'] || row['Mañana 1'] || row['manana_1'] || '';
  const morning2 = row['Manana 2'] || row['Mañana 2'] || row['manana_2'] || '';
  const afternoon1 = row['Tarde 1'] || row['tarde_1'] || '';
  const afternoon2 = row['Tarde 2'] || row['tarde_2'] || '';

  for (const name of [morning1, morning2]) {
    const trimmed = name.trim();
    if (trimmed && NAME_TO_ID[trimmed]) {
      scheduleEntries.push({
        schedule_date: todayStr,
        shift: 'morning',
        agent_id: NAME_TO_ID[trimmed],
        agent_name: trimmed
      });
    }
  }

  for (const name of [afternoon1, afternoon2]) {
    const trimmed = name.trim();
    if (trimmed && NAME_TO_ID[trimmed]) {
      scheduleEntries.push({
        schedule_date: todayStr,
        shift: 'afternoon',
        agent_id: NAME_TO_ID[trimmed],
        agent_name: trimmed
      });
    }
  }

  break; // Found today's row
}

if (scheduleEntries.length === 0) {
  return [{ json: { _action: 'no_schedule', date: todayStr, message: 'No schedule found for today' } }];
}

return [{ json: { _action: 'sync', date: todayStr, entries: scheduleEntries, count: scheduleEntries.length } }];

