// Summarize what happened for logging.
const parsed = $('Parse Today Schedule').first().json;
const activated = $input.all().map(i => i.json);

return [{
  json: {
    date: parsed.date,
    total_scheduled: parsed.count,
    activated_agents: activated.map(a => `${a.name} (${a.shift_slot})`),
    activated_count: activated.length,
    status: activated.length > 0 ? 'agents_on_shift' : 'no_active_shift'
  }
}];
